INSERT INTO "knowledge"."route_version" (route_id, number, content, content_hash, cases) VALUES
  ('es-international-telework', 1, '{"schemaVersion":1,"routeId":"es-international-telework","number":1,"title":"International telework visa and residence permit (digital nomad) for remote work for companies outside Spain","country":"ES","tags":["digital-nomad","temporary-residence"],"effectiveFrom":"2024-09-24","status":"open","currency":"EUR","sources":[{"id":"ley-14-2013-scope","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 61.1 f) and 61.2: entry and stay for international teleworkers, which does not apply to EU citizens or foreigners with equivalent free movement rights by EU agreements","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-definition","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 74 bis: a third-country national working remotely, only by telematic means, for companies outside Spain; a professional may work up to 20% for a company in Spain","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-qualification","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 74 bis.2: qualified professionals: graduates or postgraduates of universities or business schools of recognized prestige, or of vocational training, or with 3 years of experience","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-requirements","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 74 ter: the company active for a year; remote work possible; an employment relationship, or a commercial one with companies outside Spain, for at least the last three months","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-general","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 62.3: for a residence visa or permit the applicant must prove the general requirements, a) to g)","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-family","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 62.4: the spouse or partner, minor children, adult children dependent on the holder who have not formed their own family unit, and dependent ascendants may apply","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-public-order","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 62.7: permits and visas are revoked, refused or not renewed for a threat to public order, security or health, or national security, shown by an official report","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-visa","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 74 quater: the international telework visa for non-residents, valid up to a year, and the residence permit applied for in the 60 days before it expires","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-residence","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, article 74 quinquies: the residence permit for international telework, for people lawfully in Spain, valid up to three years, renewable for two years at a time","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-means-thresholds","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, twentieth additional provision: instructions set the specific requirements, and the thresholds of economic means are referenced to the minimum wage (salario mínimo interprofesional)","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-fee","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, nineteenth additional provision: a fee for its residence permits, renewals and visas, owed by the applicants, in an amount a ministerial order sets","kind":"official","verifiedAt":"2026-11-25"},{"id":"ley-14-2013-supplementary","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2013-10074","title":"Ley 14/2013, thirteenth final provision: where this law does not provide, Ley Orgánica 4/2000 applies to international mobility","kind":"official","verifiedAt":"2026-11-25"},{"id":"lo-4-2000","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","title":"Ley Orgánica 4/2000, article 1: Spanish nationals are not foreigners under this law, and EU citizens and others under the EU regime follow that regime''s rules","kind":"official","verifiedAt":"2026-11-25"},{"id":"rd-240-2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-4184","title":"Real Decreto 240/2007, article 1 and third additional provision: residence in Spain of citizens of other EU and EEA states, and of Swiss citizens","kind":"official","verifiedAt":"2026-11-25"},{"id":"lo-4-2000-fees","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","title":"Ley Orgánica 4/2000, articles 48.1 and 46.1: fee amounts set by ministerial order, owed by visa applicants","kind":"official","verifiedAt":"2026-11-25"},{"id":"lo-4-2000-reciprocity","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2000-544","title":"Ley Orgánica 4/2000, article 48.4: visa fees follow the amount that may be set by applying the principle of reciprocity","kind":"official","verifiedAt":"2026-11-25"},{"id":"orden-auc-891-2024","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2024-17292","title":"Orden AUC/891/2024, article 1 and final provision: EUR 90 for processing a national long-stay visa (type D) application, for every application from one month after its publication on 2024-08-24","kind":"official","verifiedAt":"2026-11-25"},{"id":"orden-ess-1571-2014","url":"https://www.boe.es/buscar/doc.php?id=BOE-A-2014-9064","title":"Orden ESS/1571/2014, article 1 and annex: the fee of Ley 14/2013 article 62.3 g) for residence permits, EUR 70.40 initial and 75.60 renewed, raised each year as budget laws set","kind":"official","verifiedAt":"2026-11-25"},{"id":"codigo-civil","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763","title":"Código Civil, article 5.1: a period in years with no matching day in its last month ends on that month''s last day; article 240: majority at 18","kind":"official","verifiedAt":"2026-11-25"}],"countries":{"id":"countries","number":1},"formerCountries":{"id":"former-countries","number":1},"officialDomains":[{"id":"es","number":1}],"countrySets":[{"id":"eu-free-movement","number":2}],"leapDayBirthday":"feb-28","leapDayBirthdaySources":["codigo-civil"],"requirements":[{"id":"not-eu-eea-or-swiss-citizen","title":"Not a citizen of Spain, who is no foreigner under the law, nor of another EU or EEA state or of Switzerland, whose citizens live in Spain under EU free movement rules and not on this visa","expression":{"op":"not","operand":{"op":"intersects","list":{"op":"fact","key":"principal.citizenships"},"set":{"op":"set","id":"eu-free-movement"}}},"sources":["ley-14-2013-scope","ley-14-2013-definition","lo-4-2000","rd-240-2007"]},{"id":"adult","title":"The applicant is 18 or older","expression":{"op":"gte","left":{"op":"fact","key":"principal.ageYears"},"right":{"op":"int","value":18}},"sources":["ley-14-2013-general","codigo-civil"]},{"id":"remote-relationship","title":"Works for companies seated outside Spain, still today: an employee of the same one for the last 3 months; or with clients there for the last 3 months unbroken; an owner of one is possible","expression":{"op":"any","operands":[{"op":"some","over":"principal.workPeriods","where":{"op":"all","operands":[{"op":"eq","left":{"op":"fact","key":"workPeriod.relation"},"right":{"op":"token","value":"employee"}},{"op":"ne","left":{"op":"fact","key":"workPeriod.employerCountry"},"right":{"op":"token","value":"ES"}},{"op":"since","date":{"op":"fact","key":"workPeriod.start"},"duration":"P3M"},{"op":"not","operand":{"op":"since","date":{"op":"fact","key":"workPeriod.end"},"duration":"P1D"}}]}},{"op":"all","operands":[{"op":"covers","over":"principal.workPeriods","where":{"op":"all","operands":[{"op":"in","item":{"op":"fact","key":"workPeriod.relation"},"set":{"op":"tokens","values":["contractor","self_employed"]}},{"op":"ne","left":{"op":"fact","key":"workPeriod.employerCountry"},"right":{"op":"token","value":"ES"}}]},"atLeast":"P3M","window":"P3M","continuous":true},{"op":"some","over":"principal.workPeriods","where":{"op":"all","operands":[{"op":"in","item":{"op":"fact","key":"workPeriod.relation"},"set":{"op":"tokens","values":["contractor","self_employed"]}},{"op":"ne","left":{"op":"fact","key":"workPeriod.employerCountry"},"right":{"op":"token","value":"ES"}},{"op":"not","operand":{"op":"since","date":{"op":"fact","key":"workPeriod.end"},"duration":"P1D"}}]}}]},{"op":"all","operands":[{"op":"covers","over":"principal.workPeriods","where":{"op":"all","operands":[{"op":"eq","left":{"op":"fact","key":"workPeriod.relation"},"right":{"op":"token","value":"owner"}},{"op":"ne","left":{"op":"fact","key":"workPeriod.employerCountry"},"right":{"op":"token","value":"ES"}}]},"atLeast":"P3M","window":"P3M","continuous":true},{"op":"some","over":"principal.workPeriods","where":{"op":"all","operands":[{"op":"eq","left":{"op":"fact","key":"workPeriod.relation"},"right":{"op":"token","value":"owner"}},{"op":"ne","left":{"op":"fact","key":"workPeriod.employerCountry"},"right":{"op":"token","value":"ES"}},{"op":"not","operand":{"op":"since","date":{"op":"fact","key":"workPeriod.end"},"duration":"P1D"}}]}},{"op":"unmodeled"}]}]},"sources":["ley-14-2013-requirements","ley-14-2013-definition"]}],"assessments":[{"id":"company-activity","title":"The company or group the applicant works for, or has a commercial relationship with, has had real and continued activity for at least one year","evidence":["principal.monthlyActiveIncome"],"sources":["ley-14-2013-requirements"]},{"id":"remote-work-allowed","title":"Documents show the work can be done remotely: for an employee, that the company allows it; for a professional, the terms and conditions of the remote activity","evidence":["principal.monthlyActiveIncome"],"sources":["ley-14-2013-requirements"]},{"id":"qualified-professional","title":"A qualified professional: a graduate or postgraduate of a university or business school of recognized prestige, or of vocational training, or with at least three years of professional experience","evidence":["principal.educationLevel"],"sources":["ley-14-2013-qualification"]},{"id":"work-only-for-companies-abroad","title":"In Spain, an employee works only for companies outside Spain; a professional may work for a company in Spain for no more than 20% of the whole professional activity","evidence":["principal.monthlyActiveIncome"],"sources":["ley-14-2013-definition"]},{"id":"sufficient-means","title":"Sufficient economic resources for the applicant and the family for the stay; the law refers the threshold to the minimum wage and leaves it to instructions of the competent bodies","evidence":["principal.monthlyActiveIncome","unit.liquidAssets"],"sources":["ley-14-2013-general","ley-14-2013-means-thresholds"]},{"id":"health-insurance","title":"Each applicant: public health insurance, or private health insurance with an insurer authorized to operate in Spain","evidence":["unit.liquidAssets"],"sources":["ley-14-2013-general","ley-14-2013-family"]},{"id":"criminal-record","title":"Each applicant: no criminal record, in Spain and the countries lived in during the last two years, for offences under Spanish law, plus a sworn statement of none in the last five years","evidence":["principal.residenceCountry"],"sources":["ley-14-2013-general","ley-14-2013-family"]},{"id":"not-irregularly-in-spain","title":"Each applicant: not irregularly in Spanish territory","evidence":["principal.residenceCountry"],"sources":["ley-14-2013-general","ley-14-2013-family"]},{"id":"not-listed-as-refusable","title":"Each applicant: not listed as refusable in the territory of countries with which Spain has an agreement to that effect","evidence":["principal.visaRefusals"],"sources":["ley-14-2013-general","ley-14-2013-family"]},{"id":"public-order","title":"Each applicant: no threat to public order, public security, public health or national security, as a police, intelligence or national security report may show","evidence":["principal.visaRefusals"],"sources":["ley-14-2013-public-order"]},{"id":"visa-or-permit","title":"Living abroad: the telework visa, at a consulate. Lawfully in Spain: the permit, whose fee each applicant pays (2014: EUR 70.40, renewal 75.60, raised by budget laws since), not computed here","evidence":["principal.residenceCountry"],"sources":["ley-14-2013-visa","ley-14-2013-residence","orden-ess-1571-2014"]}],"dependents":[{"id":"spouse","title":"Spouse","path":["spouse"],"condition":{"op":"bool","value":true},"sources":["ley-14-2013-family"]},{"id":"partner","title":"Partner in a relationship akin to marriage (análoga relación de afectividad); the law sets no proof of the relationship","path":["partner"],"condition":{"op":"bool","value":true},"sources":["ley-14-2013-family"]},{"id":"children","title":"Children under 18; an adult child who depends financially on the holder, is not married and has no partner is possible, as having children of their own may count as their own family unit","path":["child"],"condition":{"op":"any","operands":[{"op":"lt","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"all","operands":[{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"not","operand":{"op":"fact","key":"person.hasSpouse"}},{"op":"not","operand":{"op":"fact","key":"person.hasPartner"}},{"op":"unmodeled"}]}]},"sources":["ley-14-2013-family","codigo-civil"]},{"id":"spouse-children","title":"The spouse''s own children, on the terms of the holder''s children: possible, as the law says \"children\" and does not say whose","path":["spouse","child"],"condition":{"op":"all","operands":[{"op":"any","operands":[{"op":"lt","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"all","operands":[{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"not","operand":{"op":"fact","key":"person.hasSpouse"}},{"op":"not","operand":{"op":"fact","key":"person.hasPartner"}},{"op":"unmodeled"}]}]},{"op":"unmodeled"}]},"sources":["ley-14-2013-family","codigo-civil"]},{"id":"partner-children","title":"The partner''s own children, on the terms of the holder''s children: possible, as the law says \"children\" and does not say whose","path":["partner","child"],"condition":{"op":"all","operands":[{"op":"any","operands":[{"op":"lt","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"all","operands":[{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"not","operand":{"op":"fact","key":"person.hasSpouse"}},{"op":"not","operand":{"op":"fact","key":"person.hasPartner"}},{"op":"unmodeled"}]}]},{"op":"unmodeled"}]},"sources":["ley-14-2013-family","codigo-civil"]},{"id":"parents","title":"Parents who depend on the holder (ascendientes a cargo)","path":["parent"],"condition":{"op":"fact","key":"person.dependsOnPrincipal"},"sources":["ley-14-2013-family"]},{"id":"grandparents","title":"Grandparents who depend on the holder (ascendientes a cargo)","path":["parent","parent"],"condition":{"op":"fact","key":"person.dependsOnPrincipal"},"sources":["ley-14-2013-family"]},{"id":"spouse-parents","title":"The spouse''s parents who depend on the holder or the spouse: possible, as the law says \"dependent ascendants\" and does not say whose","path":["spouse","parent"],"condition":{"op":"all","operands":[{"op":"any","operands":[{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"fact","key":"edge.dependsOnLinkedPerson"}]},{"op":"unmodeled"}]},"sources":["ley-14-2013-family"]}],"costs":[{"id":"visa-fee","title":"Fee for the principal''s national long-stay visa (Orden AUC/891/2024, under Ley Orgánica 4/2000), when applying from abroad; reciprocity with the applicant''s country may change it, not checked","kind":"fee","amount":{"op":"money","amount":9000,"currency":"EUR"},"appliesTo":"principal","condition":{"op":"any","operands":[{"op":"not","operand":{"op":"eq","left":{"op":"fact","key":"principal.residenceCountry"},"right":{"op":"token","value":"ES"}}},{"op":"unmodeled"}]},"sources":["orden-auc-891-2024","lo-4-2000-fees","lo-4-2000-reciprocity","ley-14-2013-fee","ley-14-2013-supplementary"]},{"id":"visa-fee-dependents","title":"Fee for each family member''s national long-stay visa (Orden AUC/891/2024, under Ley Orgánica 4/2000), when applying from abroad; reciprocity with the applicant''s country may change it, not checked","kind":"fee","amount":{"op":"money","amount":9000,"currency":"EUR"},"appliesTo":"each_dependent","condition":{"op":"any","operands":[{"op":"not","operand":{"op":"eq","left":{"op":"fact","key":"principal.residenceCountry"},"right":{"op":"token","value":"ES"}}},{"op":"unmodeled"}]},"sources":["orden-auc-891-2024","lo-4-2000-fees","lo-4-2000-reciprocity","ley-14-2013-fee","ley-14-2013-supplementary"]}],"durations":[{"id":"visa","title":"The telework visa, which is enough to live and work remotely in Spain; shorter when the work period is shorter","min":"P0D","max":"P1Y","sources":["ley-14-2013-visa"]},{"id":"permit-application-window","title":"To stay on, the residence permit is applied for within the 60 calendar days before the visa expires, while the conditions still hold","min":"P0D","max":"P60D","sources":["ley-14-2013-visa"]},{"id":"residence-permit","title":"The residence permit for international telework, shorter when applied for a shorter work period","min":"P0D","max":"P3Y","sources":["ley-14-2013-residence"]},{"id":"renewal","title":"Each renewal, while the conditions that gave the right still hold","min":"P2Y","max":"P2Y","sources":["ley-14-2013-residence"]}],"documents":[{"id":"company-activity-proof","title":"Proof that the company or group of companies has had real and continued activity for at least one year","kind":"company_activity_proof","appliesTo":"principal","sources":["ley-14-2013-requirements"]},{"id":"remote-work-proof","title":"Documents showing that the employment or professional relationship can be carried out remotely","kind":"remote_work_proof","appliesTo":"principal","sources":["ley-14-2013-requirements"]},{"id":"employment-proof","title":"Employee: proof of the employment relationship with the company outside Spain for at least the last three months, and that the company lets the employee work remotely","kind":"employment_contract","appliesTo":"principal","condition":{"op":"unmodeled"},"sources":["ley-14-2013-requirements"]},{"id":"professional-proof","title":"Professional: proof of a commercial relationship with one or more companies outside Spain for at least the last three months, and the terms and conditions of the remote work","kind":"service_contract","appliesTo":"principal","condition":{"op":"unmodeled"},"sources":["ley-14-2013-requirements"]},{"id":"qualification-proof","title":"Proof of being a graduate or postgraduate of a university or business school of recognized prestige, or of vocational training, or of at least three years of professional experience","kind":"qualification_proof","appliesTo":"principal","sources":["ley-14-2013-qualification"]},{"id":"criminal-record-proof","title":"Proof of no criminal record in Spain and in the countries lived in during the last two years, for offences under Spanish law","kind":"police_certificate","appliesTo":"principal","sources":["ley-14-2013-general"]},{"id":"criminal-record-statement","title":"A sworn statement (declaración responsable) of no criminal record in the last five years","kind":"criminal_record_statement","appliesTo":"principal","sources":["ley-14-2013-general"]},{"id":"health-insurance-proof","title":"Public health insurance, or private health insurance with an insurer authorized to operate in Spain","kind":"health_insurance","appliesTo":"principal","sources":["ley-14-2013-general"]},{"id":"means-proof","title":"Proof of sufficient economic resources for the applicant and the family members for the stay in Spain","kind":"means_of_subsistence_proof","appliesTo":"unit","sources":["ley-14-2013-general","ley-14-2013-family"]},{"id":"criminal-record-proof-dependent","title":"Proof of no criminal record in Spain and in the countries lived in during the last two years, for offences under Spanish law","kind":"police_certificate","appliesTo":"each_dependent","note":"The law asks each family member to prove the same requirements as the applicant","sources":["ley-14-2013-general","ley-14-2013-family"]},{"id":"criminal-record-statement-dependent","title":"A sworn statement (declaración responsable) of no criminal record in the last five years","kind":"criminal_record_statement","appliesTo":"each_dependent","note":"The law asks each family member to prove the same requirements as the applicant","sources":["ley-14-2013-general","ley-14-2013-family"]},{"id":"health-insurance-proof-dependent","title":"Public health insurance, or private health insurance with an insurer authorized to operate in Spain","kind":"health_insurance","appliesTo":"each_dependent","sources":["ley-14-2013-general","ley-14-2013-family"]}]}'::jsonb, '3e3687b28c36046474b0cf4b9a9b4ed926930a6b8475b2dd07035863c457b226', '{"schemaVersion":1,"cases":[{"id":"remote-employee-of-a-brazilian-company-with-family","snapshot":{"recordedOn":"2026-10-01","members":["p1","p2","p3","p4","p5","p6","p7","p8","p9","p10","p11","p12","p13","p14"],"people":[{"id":"p1","birthDate":"1984-05-10","citizenships":[{"country":"BR","acquired":"1984-05-10","lost":"none","basis":"birth"}],"residenceCountry":"BR","incomes":[],"financiallyDependentOn":[],"studying":false,"recordedInFull":["spouses","partners","children","parents","assets"],"workPeriods":[{"employerCountry":"BR","workplaceCountry":"BR","relation":"employee","start":"2021-02-01","end":"none"}],"educationLevel":6},{"id":"p2","birthDate":"1986-08-03","citizenships":[{"country":"BR","acquired":"1986-08-03","lost"